import { describe, it, expect, afterEach } from "vitest";
import { readFileSync, existsSync, unlinkSync } from "node:fs";
import { join, resolve } from "node:path";
import { spawnSync } from "node:child_process";
import {
  writePerModuleRouteTypesForFile,
  writeCombinedRouteTypes,
} from "../generate-route-types";
import { discoverAndWriteRouteTypes } from "../runtime-discovery";

const fixtureDir = join(__dirname, "__fixtures__", "app");

// Track generated files for cleanup
const generatedFiles: string[] = [];

function genPathFor(filePath: string): string {
  return filePath.replace(/\.tsx?$/, ".gen.ts");
}

function namedRoutesGenPathFor(filePath: string): string {
  return filePath.replace(/\.tsx?$/, ".named-routes.gen.ts");
}

afterEach(() => {
  for (const f of generatedFiles) {
    try {
      if (existsSync(f)) unlinkSync(f);
    } catch {}
  }
  generatedFiles.length = 0;
});

describe("generate-cli e2e fixtures", () => {
  // -----------------------------------------------------------------------
  // Per-module generation
  // -----------------------------------------------------------------------

  describe("writePerModuleRouteTypesForFile", () => {
    it("generates correct routes for main urls module with includes", () => {
      const mainUrls = join(fixtureDir, "urls.tsx");
      writePerModuleRouteTypesForFile(mainUrls);

      const genFile = genPathFor(mainUrls);
      generatedFiles.push(genFile);
      expect(existsSync(genFile)).toBe(true);

      const content = readFileSync(genFile, "utf-8");

      // Header
      expect(content).toMatch(/^\/\/ Auto-generated by @rangojs\/router/);

      // Local routes
      expect(content).toContain('home: "/",');
      expect(content).toContain('about: "/about",');

      // API include (prefixed names and patterns)
      expect(content).toContain('"api.health"');
      expect(content).toContain("/api/health");
      expect(content).toContain('"api.detail"');
      expect(content).toContain("/api/:id");
      expect(content).toContain('"api.search"');
      expect(content).toContain("/api/search");

      // Docs include
      expect(content).toContain('"docs.page"');
      expect(content).toContain("/docs/:slug");

      // 3-level deep include (app -> docs -> guides)
      expect(content).toContain('"docs.guides.index"');
      expect(content).toContain("/docs/guides");
      expect(content).toContain('"docs.guides.detail"');
      expect(content).toContain("/docs/guides/:guideId");
    });

    it("generates only local routes for a sub-module", () => {
      const apiUrls = join(fixtureDir, "api", "urls.tsx");
      writePerModuleRouteTypesForFile(apiUrls);

      const genFile = genPathFor(apiUrls);
      generatedFiles.push(genFile);
      expect(existsSync(genFile)).toBe(true);

      const content = readFileSync(genFile, "utf-8");

      // API routes without prefix (module-level view)
      expect(content).toContain('health: "/health",');
      expect(content).toContain("detail:");
      expect(content).toContain("/:id");
      expect(content).toContain("search:");
      expect(content).toContain("/search");

      // Should NOT contain any prefixed names from parent
      expect(content).not.toContain("api.");
      expect(content).not.toContain("home");
      expect(content).not.toContain("about");
    });

    it("keeps parameterized patterns as plain strings (params extracted at type level)", () => {
      const apiUrls = join(fixtureDir, "api", "urls.tsx");
      writePerModuleRouteTypesForFile(apiUrls);

      const genFile = genPathFor(apiUrls);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // /:id stays as plain string — ExtractParams resolves params at the type level
      expect(content).toContain('detail: "/:id",');
    });

    it("extracts search schemas", () => {
      const apiUrls = join(fixtureDir, "api", "urls.tsx");
      writePerModuleRouteTypesForFile(apiUrls);

      const genFile = genPathFor(apiUrls);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // search route should have search: { q: "string", page: "number?" }
      expect(content).toContain('search: { q: "string", page: "number?" }');
    });

    it("handles 3-level deep includes (app -> docs -> guides)", () => {
      const mainUrls = join(fixtureDir, "urls.tsx");
      writePerModuleRouteTypesForFile(mainUrls);

      const genFile = genPathFor(mainUrls);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // Guides routes should have chained prefixes
      expect(content).toContain('"docs.guides.index"');
      expect(content).toContain('"docs.guides.detail"');

      // Patterns should have chained path prefixes
      expect(content).toContain("/docs/guides");
      expect(content).toContain("/docs/guides/:guideId");
    });

    it("preserves param patterns in deeply nested routes", () => {
      const mainUrls = join(fixtureDir, "urls.tsx");
      writePerModuleRouteTypesForFile(mainUrls);

      const genFile = genPathFor(mainUrls);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // docs.page has /:slug in the pattern string
      expect(content).toContain('"docs.page": "/docs/:slug",');

      // docs.guides.detail has /:guideId in the pattern string
      expect(content).toContain(
        '"docs.guides.detail": "/docs/guides/:guideId",',
      );
    });

    it("propagates search schemas through includes", () => {
      const mainUrls = join(fixtureDir, "urls.tsx");
      writePerModuleRouteTypesForFile(mainUrls);

      const genFile = genPathFor(mainUrls);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // api.search should carry its search schema through the include
      expect(content).toContain('"api.search"');
      expect(content).toContain('q: "string"');
      expect(content).toContain('page: "number?"');
    });

    it("generates routes for the docs sub-module with nested include", () => {
      const docsUrls = join(fixtureDir, "docs", "urls.tsx");
      writePerModuleRouteTypesForFile(docsUrls);

      const genFile = genPathFor(docsUrls);
      generatedFiles.push(genFile);
      expect(existsSync(genFile)).toBe(true);

      const content = readFileSync(genFile, "utf-8");

      // Local route
      expect(content).toContain("page:");
      expect(content).toContain("/:slug");

      // Included guides routes (one level of prefix)
      expect(content).toContain('"guides.index"');
      expect(content).toContain("/guides");
      expect(content).toContain('"guides.detail"');
      expect(content).toContain("/guides/:guideId");
    });

    it("generates routes for the leaf guides module", () => {
      const guidesUrls = join(fixtureDir, "docs", "guides", "urls.tsx");
      writePerModuleRouteTypesForFile(guidesUrls);

      const genFile = genPathFor(guidesUrls);
      generatedFiles.push(genFile);
      expect(existsSync(genFile)).toBe(true);

      const content = readFileSync(genFile, "utf-8");

      // Leaf module routes without any prefix
      expect(content).toContain('index: "/",');
      expect(content).toContain('detail: "/:guideId",');

      // Should not contain parent prefixes
      expect(content).not.toContain("docs.");
      expect(content).not.toContain("guides.");
    });
  });

  // -----------------------------------------------------------------------
  // Named-routes generation for router files
  // -----------------------------------------------------------------------

  describe("writeCombinedRouteTypes (router file)", () => {
    it("generates named-routes.gen.ts with full merged route map", () => {
      const routerFile = join(fixtureDir, "router.tsx");
      writeCombinedRouteTypes(fixtureDir, [routerFile]);

      const genFile = namedRoutesGenPathFor(routerFile);
      generatedFiles.push(genFile);
      expect(existsSync(genFile)).toBe(true);

      const content = readFileSync(genFile, "utf-8");

      // Header
      expect(content).toMatch(/^\/\/ Auto-generated by @rangojs\/router/);

      // Global augmentation
      expect(content).toContain("declare global");
      expect(content).toContain("namespace RSCRouter");
      expect(content).toContain("GeneratedRouteMap");
      expect(content).toContain("NamedRoutes");

      // All routes from the full tree
      expect(content).toContain('home: "/"');
      expect(content).toContain('about: "/about"');
      expect(content).toContain("/api/health");
      expect(content).toContain("/api/:id");
      expect(content).toContain("/api/search");
      expect(content).toContain("/docs/:slug");
      expect(content).toContain("/docs/guides");
      expect(content).toContain("/docs/guides/:guideId");
    });

    it("includes search schemas and param patterns in named-routes output", () => {
      const routerFile = join(fixtureDir, "router.tsx");
      writeCombinedRouteTypes(fixtureDir, [routerFile]);

      const genFile = namedRoutesGenPathFor(routerFile);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // Parameterized routes are plain strings (params extracted at type level)
      expect(content).toContain('"api.detail": "/api/:id",');
      expect(content).toContain('"docs.page": "/docs/:slug",');
      expect(content).toContain(
        '"docs.guides.detail": "/docs/guides/:guideId",',
      );

      // api.search has search schema (object format)
      expect(content).toContain('q: "string"');
      expect(content).toContain('page: "number?"');
    });

    it("sorts routes alphabetically by name", () => {
      const routerFile = join(fixtureDir, "router.tsx");
      writeCombinedRouteTypes(fixtureDir, [routerFile]);

      const genFile = namedRoutesGenPathFor(routerFile);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // Extract route names in order from the generated file
      const nameMatches = [...content.matchAll(/^\s+(?:"([^"]+)"|(\w+)):/gm)];
      const names = nameMatches.map((m) => m[1] ?? m[2]);

      // Verify sorted order
      const sorted = [...names].sort((a, b) => a!.localeCompare(b!));
      expect(names).toEqual(sorted);
    });
  });

  // -----------------------------------------------------------------------
  // Deduplication
  // -----------------------------------------------------------------------

  describe("first-wins dedup", () => {
    it("keeps first definition when route name appears twice", () => {
      // The main urls module includes api which has a "detail" route.
      // The docs module also has a "page" route. These are distinct names.
      // To test dedup, generate for api/urls which has unique names.
      const apiUrls = join(fixtureDir, "api", "urls.tsx");
      writePerModuleRouteTypesForFile(apiUrls);

      const genFile = genPathFor(apiUrls);
      generatedFiles.push(genFile);
      const content = readFileSync(genFile, "utf-8");

      // Each name should appear exactly once in the routes object
      const detailMatches = content.match(/\bdetail\b/g);
      // "detail" appears in the route entry key and potentially in the path/params
      // but the key itself should only appear once as a route definition
      const detailKeyMatches = content.match(/^\s+detail:/gm);
      expect(detailKeyMatches).toHaveLength(1);
    });
  });
});

// ---------------------------------------------------------------------------
// Factory fixture (app-with-factory)
// ---------------------------------------------------------------------------

describe("factory fixture", () => {
  afterEach(() => {
    // Clean up gen files in factory fixture
    const possibleGens = [
      factoryGenPath,
      factoryUrlsGenPath,
      factoryApiUrlsGenPath,
    ];
    for (const f of possibleGens) {
      try {
        if (existsSync(f)) unlinkSync(f);
      } catch {}
    }
  });

  it("produces partial gen file with API routes but no docs routes", () => {
    const routerFile = join(factoryFixtureDir, "router.tsx");
    const routerDir = join(factoryFixtureDir);

    writeCombinedRouteTypes(routerDir, [routerFile]);

    const genPath = join(factoryFixtureDir, "router.named-routes.gen.ts");
    expect(existsSync(genPath)).toBe(true);

    const content = readFileSync(genPath, "utf-8");
    // API routes should be present (statically resolvable)
    expect(content).toContain("api.health");
    expect(content).toContain("api.detail");
    // Static top-level routes should be present
    expect(content).toContain("home");
    expect(content).toContain("about");
    // Docs routes should NOT be present (factory call, unresolvable)
    expect(content).not.toContain("docs.index");
    expect(content).not.toContain("docs.page");
  });

  it("runtime discovery produces complete output including factory routes", async () => {
    const packageRoot = resolve(__dirname, "..", "..", "..");
    const srcDir = join(packageRoot, "src");
    const genPath = join(factoryFixtureDir, "router.named-routes.gen.ts");
    generatedFiles.push(genPath);

    const result = await discoverAndWriteRouteTypes({
      root: packageRoot,
      entry: join(factoryFixtureDir, "router.tsx"),
      resolveAlias: {
        "@rangojs/router/server": join(srcDir, "server.ts"),
        "@rangojs/router/build": join(srcDir, "build", "index.ts"),
        "@rangojs/router/cache": join(srcDir, "cache", "index.ts"),
        "@rangojs/router/host": join(srcDir, "host", "index.ts"),
        "@rangojs/router": join(srcDir, "index.rsc.ts"),
      },
    });

    expect(result.routerCount).toBe(1);
    // 7 user-named routes (unnamed "$path_..." routes are filtered from output)
    expect(result.routeCount).toBe(7);

    const content = readFileSync(genPath, "utf-8");
    // Static routes present
    expect(content).toContain("home");
    expect(content).toContain("about");
    expect(content).toContain("api.health");
    expect(content).toContain("api.detail");
    // Factory routes also present (the key difference from static-only)
    expect(content).toContain("docs.index");
    expect(content).toContain("docs.page");
    // User-defined name with "$" is preserved (not filtered as auto-generated)
    expect(content).toContain('"docs.$admin"');
  }, 30_000);

  it("runtime discovery excludes internal auto-generated $ names from gen file", async () => {
    const packageRoot = resolve(__dirname, "..", "..", "..");
    const srcDir = join(packageRoot, "src");
    const genPath = join(factoryFixtureDir, "router.named-routes.gen.ts");
    generatedFiles.push(genPath);

    await discoverAndWriteRouteTypes({
      root: packageRoot,
      entry: join(factoryFixtureDir, "router.tsx"),
      resolveAlias: {
        "@rangojs/router/server": join(srcDir, "server.ts"),
        "@rangojs/router/build": join(srcDir, "build", "index.ts"),
        "@rangojs/router/cache": join(srcDir, "cache", "index.ts"),
        "@rangojs/router/host": join(srcDir, "host", "index.ts"),
        "@rangojs/router": join(srcDir, "index.rsc.ts"),
      },
    });

    const content = readFileSync(genPath, "utf-8");
    // The factory fixture has an unnamed route (path("/health", handler) with no name).
    // Its auto-generated "$path_..." name must not appear in the gen file.
    // The include prefix "docs" means the full name is "docs.$path__health".
    expect(content).not.toMatch(/\$path_/);
    // But user-named routes must still be present
    expect(content).toContain("docs.index");
    expect(content).toContain("docs.page");
    // User-defined name with "$" (docs.$admin) must be preserved — only
    // the "$path_" auto-generated prefix triggers filtering, not bare "$".
    expect(content).toContain('"docs.$admin"');
  }, 30_000);
});

// ---------------------------------------------------------------------------
// CLI command-level tests: spawn `rango generate` as a subprocess
// ---------------------------------------------------------------------------

const packageRoot = resolve(__dirname, "..", "..", "..");
const rangoBin = join(packageRoot, "dist", "bin", "rango.js");
const staticFixtureRouter = join(
  __dirname,
  "__fixtures__",
  "app",
  "router.tsx",
);
const factoryFixtureRouter = join(
  __dirname,
  "__fixtures__",
  "app-with-factory",
  "router.tsx",
);
const factoryFixtureDir = join(__dirname, "__fixtures__", "app-with-factory");
const factoryFixtureUrls = join(factoryFixtureDir, "urls.tsx");
const factoryGenPath = join(factoryFixtureDir, "router.named-routes.gen.ts");
const factoryUrlsGenPath = join(factoryFixtureDir, "urls.gen.ts");
const factoryApiUrlsGenPath = join(factoryFixtureDir, "api", "urls.gen.ts");
const factoryFactoryGenPath = join(factoryFixtureDir, "factory.gen.ts");
const staticGenPath = join(
  __dirname,
  "__fixtures__",
  "app",
  "router.named-routes.gen.ts",
);

function runRango(args: string) {
  const result = spawnSync("node", [rangoBin, ...args.split(" ")], {
    encoding: "utf-8",
    cwd: packageRoot,
    timeout: 30_000,
  });
  return {
    ...result,
    combined: `${result.stdout ?? ""}${result.stderr ?? ""}`,
  };
}

describe("CLI command-level tests", () => {
  afterEach(() => {
    for (const f of [
      factoryGenPath,
      factoryUrlsGenPath,
      factoryApiUrlsGenPath,
      factoryFactoryGenPath,
      staticGenPath,
    ]) {
      try {
        if (existsSync(f)) unlinkSync(f);
      } catch {}
    }
  });

  // --- Happy paths ---

  it("default mode succeeds for fully static router", () => {
    const result = runRango(`generate ${staticFixtureRouter}`);
    expect(result.status).toBe(0);
    expect(existsSync(staticGenPath)).toBe(true);

    const content = readFileSync(staticGenPath, "utf-8");
    expect(content).toContain("home");
    expect(content).toContain("about");
    expect(content).toContain("api.health");
  });

  it("--runtime succeeds for factory router and includes factory routes", () => {
    const result = runRango(`generate ${factoryFixtureRouter} --runtime`);
    expect(result.status).toBe(0);
    expect(existsSync(factoryGenPath)).toBe(true);

    const content = readFileSync(factoryGenPath, "utf-8");
    // Static routes
    expect(content).toContain("home");
    expect(content).toContain("about");
    expect(content).toContain("api.health");
    // Factory routes (invisible to static parser)
    expect(content).toContain("docs.index");
    expect(content).toContain("docs.page");
    // No internal $ names
    expect(content).not.toMatch(/\$path/);
  }, 30_000);

  // --- Non-happy paths ---

  it("default mode hard-fails on unresolvable factory includes", () => {
    const result = runRango(`generate ${factoryFixtureRouter}`);
    expect(result.status).not.toBe(0);
    // Error output should include the diagnostic and point to --runtime
    expect(result.combined).toContain("Unresolvable includes detected");
    expect(result.combined).toContain("docs.");
    expect(result.combined).toContain("--runtime");
    expect(result.combined).toContain("--static");
  });

  it("--static warns and emits partial output without factory routes", () => {
    const result = runRango(`generate ${factoryFixtureRouter} --static`);
    expect(result.status).toBe(0);
    // Warning about partial output
    expect(result.combined).toContain("partial output");
    expect(result.combined).toContain("factory-call");

    expect(existsSync(factoryGenPath)).toBe(true);
    const content = readFileSync(factoryGenPath, "utf-8");
    // Static routes present
    expect(content).toContain("home");
    expect(content).toContain("about");
    expect(content).toContain("api.health");
    // Factory routes absent
    expect(content).not.toContain("docs.index");
    expect(content).not.toContain("docs.page");
  });

  it("--config without --runtime is ignored with a warning", () => {
    const result = runRango(
      `generate ${staticFixtureRouter} --config some-config.ts`,
    );
    expect(result.status).toBe(0);
    expect(result.combined).toContain(
      "--config is only used with --runtime, ignoring",
    );
  });

  // --- Atomicity (P20 / E11) ---

  it("default mode directory generation is atomic: no partial gen files on failure", () => {
    const result = runRango(`generate ${factoryFixtureDir}`);
    expect(result.status).not.toBe(0);
    expect(result.combined).toContain("Unresolvable includes detected");

    // No gen files should have been written — the command failed before
    // reaching the write phase.
    expect(existsSync(factoryGenPath)).toBe(false);
    expect(existsSync(factoryUrlsGenPath)).toBe(false);
    expect(existsSync(factoryApiUrlsGenPath)).toBe(false);
    expect(existsSync(factoryFactoryGenPath)).toBe(false);
  });

  // --- Standalone urls() fail-fast (P21 / E12) ---

  it("default mode fails for standalone urls() with unresolvable factory include", () => {
    const result = runRango(`generate ${factoryFixtureUrls}`);
    expect(result.status).not.toBe(0);
    expect(result.combined).toContain("Unresolvable includes detected");
    expect(result.combined).toContain("factory-call");
    expect(result.combined).toContain("--runtime");
    expect(result.combined).toContain("--static");

    // No gen file should have been written
    expect(existsSync(factoryUrlsGenPath)).toBe(false);
  });

  it("--static mode succeeds for standalone urls() with partial output", () => {
    const result = runRango(`generate ${factoryFixtureUrls} --static`);
    expect(result.status).toBe(0);
    expect(result.combined).toContain("partial output");

    expect(existsSync(factoryUrlsGenPath)).toBe(true);
    const content = readFileSync(factoryUrlsGenPath, "utf-8");
    // Static routes present
    expect(content).toContain("home");
    expect(content).toContain("about");
    expect(content).toContain('"api.health"');
    // Factory routes absent (unresolvable)
    expect(content).not.toContain("docs.index");
    expect(content).not.toContain("docs.page");
  });
});
